python - <<'PY'
rows=[]
for line in open('/app/graphene.dat'):
 a,b=line.strip().split('\t'); rows.append((float(a.replace(',','.')),float(b.replace(',','.'))))
# List all points near plausible optical Raman shifts, every point in sections but compressed stats by x bins
for lo,hi,step in [(18500,19500,50),(16000,18500,100),(12500,16000,100),(3000,5000,100)]:
 print('\nRANGE',lo,hi)
 bins=[]
 for x,y in rows:
  if lo<=x<=hi:
   k=int((x-lo)//step)
   while len(bins)<=k: bins.append([])
   bins[k].append((x,y))
 for k,b in enumerate(bins):
  if b:
   sm=sum(y for x,y in b)/len(b); mx=max(b,key=lambda z:z[1]);
   print(f'{lo+k*step:7.0f}-{lo+(k+1)*step:7.0f} n={len(b):2d} mean={sm:9.1f} max=({mx[0]:.1f},{mx[1]:.1f})')
PY

