python - <<'PY'
# print G and 2D values and simple fitted preds for chosen parameters
rows=[]
for line in open('/app/graphene.dat'):
 a,b=line.strip().split('\t');rows.append((float(a.replace(',','.')),float(b.replace(',','.'))))
for name,x0,g,a,o,lo,hi in [('G',3745.375,24.2498,12297.4747,1290.122,3500,4000),('2D',6327.981,35.1002,8369.8791,5638.5538,6100,6550)]:
 print('\n',name)
 for x,y in rows:
  if lo<=x<=hi and (abs(x-x0)<100 or (name=='G' and (3700<x<3800)) or(name=='2D' and (6250<x<6400))):
   p=o+a/(1+((x-x0)/g)**2)
   print(f'{x:11.3f} y={y:9.2f} pred={p:9.2f} res={y-p:8.2f}')
PY

